package tags

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

// goldenTargets maps a testdata/*.json fixture base name to the Target that
// produced it. Fixtures are generated by tags/testdata/gen_goldens.py from
// the reference Python "packaging" library; see that script for exact
// generation parameters.
var goldenTargets = map[string]Target{
	"windows-amd64.json": {Implementation: "cp", PyMajor: 3, PyMinor: 11, OS: "windows", Arch: "amd64"},
	"generic-py3.json":   {Implementation: "py", PyMajor: 3, PyMinor: 11, OS: "windows", Arch: "amd64"},
	"cp311_glibc228_x86_64.json": {
		Implementation: "cp", PyMajor: 3, PyMinor: 11, OS: "linux", Arch: "x86_64",
		Libc: "glibc", LibcMajor: 2, LibcMinor: 28,
	},
	"cp39_glibc217_aarch64.json": {
		Implementation: "cp", PyMajor: 3, PyMinor: 9, OS: "linux", Arch: "aarch64",
		Libc: "glibc", LibcMajor: 2, LibcMinor: 17,
	},
	"cp312_musl12_x86_64.json": {
		Implementation: "cp", PyMajor: 3, PyMinor: 12, OS: "linux", Arch: "x86_64",
		Libc: "musl", LibcMajor: 1, LibcMinor: 2,
	},
	"cp310_macos12_arm64.json": {
		Implementation: "cp", PyMajor: 3, PyMinor: 10, OS: "macos", Arch: "arm64",
		MacMajor: 12, MacMinor: 0,
	},
	"cp312_macos14_x86_64.json": {
		Implementation: "cp", PyMajor: 3, PyMinor: 12, OS: "macos", Arch: "x86_64",
		MacMajor: 14, MacMinor: 0,
	},
}

// TestGolden asserts that Target.Compile().Tags(), stringified in order,
// exactly matches the ordered tag list recorded by gen_goldens.py.
func TestGolden(t *testing.T) {
	files, _ := filepath.Glob("testdata/*.json")
	require.NotEmpty(t, files)
	for _, f := range files {
		name := filepath.Base(f)
		t.Run(name, func(t *testing.T) {
			var want []string
			b, err := os.ReadFile(f)
			require.NoError(t, err)
			require.NoError(t, json.Unmarshal(b, &want))
			tg, ok := goldenTargets[name]
			require.True(t, ok, "no Target mapping for %s", name)
			m, err := tg.Compile()
			require.NoError(t, err)
			var got []string
			for _, tag := range m.Tags() {
				got = append(got, tag.String())
			}
			require.Equal(t, want, got)
		})
	}
}
